export async function generateReportPDF(report: ReportData): Promise<void> {
  const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
  const pageWidth = doc.internal.pageSize.getWidth();
  const today = new Date();
  const timestamp = today.toLocaleString("en-GB", { dateStyle: "long", timeStyle: "short" });
  const verifyCode = `RQ-${report.id}-${today.getTime().toString(36).toUpperCase()}`;

  const sender = SENDER_BY_APP[report.source] || { name: report.requestedBy || "System", role: "Report Sender", unit: "RIQABAH System" };
  const signer = { name: "Commander TC", role: "RIQABAH Operations Commander", unit: "Command Center" };

  // ============================
  // HEADER — Logo + Title + FROM
  // ============================
  // Logo RIQABAH asli (base64 embedded, ukuran 201 KB)
  const LOGO_BASE64 = "data:image/png;base64,";
  try {
    doc.addImage(LOGO_BASE64, "PNG", 15, 10, 36, 16);
  } catch (e) {
    // Fallback kotak hijau
    doc.setFillColor(5, 150, 105);
    doc.roundedRect(15, 12, 32, 14, 2, 2, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(11);
    doc.setFont("helvetica", "bold");
    doc.text("RIQABAH", 31, 18, { align: "center" });
  }



  // Report ID (kanan atas)
  doc.setTextColor(100, 116, 139);
  doc.setFontSize(7);
  doc.text("REPORT ID", pageWidth - 15, 14, { align: "right" });
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text(report.id, pageWidth - 15, 20, { align: "right" });

  doc.setDrawColor(5, 150, 105);
  doc.setLineWidth(0.5);
  doc.line(15, 28, pageWidth - 15, 28);

  // ============================
  // TITLE + FROM (Apps Unit)
  // ============================
  const content = REPORT_DATA[report.type] || {
    title: report.name,
    headers: ["Field", "Value"],
    rows: [["Report ID", report.id], ["Type", report.type], ["Source", report.source], ["Date", report.date]],
  };

  doc.setTextColor(15, 23, 42);
  doc.setFontSize(18);
  doc.setFont("helvetica", "bold");
  doc.text(content.title, 15, 40);

  // FROM line (apps unit)
  doc.setFontSize(8);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(100, 116, 139);
  doc.text("FROM:", 15, 46);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(5, 150, 105);
  doc.text(`${report.source} — ${sender.unit}`, 26, 46);

  // Meta line
  doc.setFontSize(8);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(100, 116, 139);
  doc.text(`Generated: ${timestamp}  ·  Period: ${report.period || "This Month"}`, 15, 51);

  // ============================
  // INFO GRID
  // ============================
  doc.setFillColor(240, 253, 244);
  doc.roundedRect(15, 56, pageWidth - 30, 22, 2, 2, "F");

  doc.setFontSize(7);
  doc.setTextColor(100, 116, 139);
  doc.text("REPORT TYPE", 20, 61);
  doc.text("DATE", 75, 61);
  doc.text("SENT BY", 110, 61);
  doc.text("VERIFICATION CODE", 155, 61);

  doc.setFontSize(9);
  doc.setTextColor(15, 23, 42);
  doc.setFont("helvetica", "bold");
  doc.text(report.type, 20, 67);
  doc.text(report.date, 75, 67);
  doc.text(sender.name, 110, 67);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.text(verifyCode, 155, 67);

  // ============================
  // DATA TABLE
  // ============================
  autoTable(doc, {
    startY: 84,
    head: [content.headers],
    body: content.rows.map(row => row.map(String)),
    theme: "striped",
    headStyles: { fillColor: [5, 150, 105], textColor: 255, fontStyle: "bold", fontSize: 8 },
    bodyStyles: { fontSize: 8, textColor: [51, 65, 85] },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    margin: { left: 15, right: 15 },
  });

  // ============================
  // NOTE
  // ============================
  let yPos = (doc as any).lastAutoTable?.finalY || 100;
  if (report.note) {
    doc.setFillColor(254, 243, 199);
    doc.roundedRect(15, yPos + 6, pageWidth - 30, 14, 2, 2, "F");
    doc.setFontSize(7);
    doc.setTextColor(146, 64, 14);
    doc.setFont("helvetica", "bold");
    doc.text("NOTE", 20, yPos + 11);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.text(report.note, 20, yPos + 16);
    yPos += 20;
  }

  // ============================
  // SIGNATURE BLOCK (3 kolom)
  // ============================
  const sigY = Math.max(yPos + 30, 230);

  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.3);
  doc.line(15, sigY - 4, pageWidth - 15, sigY - 4);

  // --- KIRI: SIGNED BY ---
  doc.setFontSize(7);
  doc.setTextColor(100, 116, 139);
  doc.setFont("helvetica", "normal");
  doc.text("SIGNED BY", 15, sigY);

  doc.setFontSize(16);
  doc.setFont("times", "italic");
  doc.setTextColor(6, 95, 70);
  doc.text(signer.name, 15, sigY + 9);

  doc.setDrawColor(15, 23, 42);
  doc.setLineWidth(0.3);
  doc.line(15, sigY + 11, 75, sigY + 11);

  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text(signer.name, 15, sigY + 16);
  doc.setFontSize(7);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(100, 116, 139);
  doc.text(signer.role, 15, sigY + 20);
  doc.text(signer.unit, 15, sigY + 23);
  doc.text(`Signed: ${timestamp}`, 15, sigY + 27);

  // --- TENGAH: SENT BY ---
  doc.setFontSize(7);
  doc.setTextColor(100, 116, 139);
  doc.setFont("helvetica", "normal");
  doc.text("SENT BY", 85, sigY);

  doc.setFontSize(16);
  doc.setFont("times", "italic");
  doc.setTextColor(37, 99, 235);
  doc.text(sender.name, 85, sigY + 9);

  doc.setDrawColor(15, 23, 42);
  doc.setLineWidth(0.3);
  doc.line(85, sigY + 11, 145, sigY + 11);

  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(15, 23, 42);
  doc.text(sender.name, 85, sigY + 16);
  doc.setFontSize(7);
  doc.setFont("helvetica", "normal");
  doc.setTextColor(100, 116, 139);
  doc.text(sender.role, 85, sigY + 20);
  doc.text(sender.unit, 85, sigY + 23);
  doc.text(`Source App: ${report.source}`, 85, sigY + 27);

  // --- KANAN: QR CODE ---
  const qrX = pageWidth - 55;
  const qrY = sigY - 2;
  const qrSize = 35;

  try {
    const verifyUrl = `https://riqabah.sa/verify/${verifyCode}`;
    const qrDataUrl = await QRCode.toDataURL(verifyUrl, {
      width: 300,
      margin: 1,
      color: { dark: "#065f46", light: "#ffffff" },
      errorCorrectionLevel: "M",
    });
    doc.addImage(qrDataUrl, "PNG", qrX, qrY, qrSize, qrSize);

    doc.setDrawColor(5, 150, 105);
    doc.setLineWidth(0.5);
    doc.roundedRect(qrX - 1, qrY - 1, qrSize + 2, qrSize + 2, 2, 2, "S");
  } catch (qrErr) {
    console.error("QR generation failed:", qrErr);
    doc.setDrawColor(5, 150, 105);
    doc.roundedRect(qrX, qrY, qrSize, qrSize, 2, 2, "S");
    doc.setFontSize(7);
    doc.setTextColor(5, 150, 105);
    doc.text("QR ERROR", qrX + qrSize / 2, qrY + qrSize / 2, { align: "center" });
  }

  doc.setFontSize(7);
  doc.setTextColor(100, 116, 139);
  doc.setFont("helvetica", "normal");
  doc.text("Scan to verify", qrX + qrSize / 2, qrY + qrSize + 4, { align: "center" });

  doc.setFontSize(6);
  doc.setFont("courier", "normal");
  doc.text(verifyCode, qrX + qrSize / 2, qrY + qrSize + 8, { align: "center" });

  // ============================
  // FOOTER
  // ============================
  const footerY = doc.internal.pageSize.getHeight() - 15;
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.3);
  doc.line(15, footerY - 4, pageWidth - 15, footerY - 4);

  doc.setFontSize(7);
  doc.setTextColor(148, 163, 184);
  doc.setFont("helvetica", "normal");
  doc.text("© 2026 RIQABAH — Halal Slaughter Intelligence. All rights reserved.", pageWidth / 2, footerY, { align: "center" });
  doc.text(`This document is electronically generated. Verify at riqabah.sa/verify/${verifyCode}`, pageWidth / 2, footerY + 4, { align: "center" });

  doc.save(`RIQABAH_${report.id}_${report.type.replace(/\s/g, "_")}.pdf`);
}


